  insert into public.strike_quiz_questions
    (id, module_version_id, tenant_id, library_scope, question_type, prompt, explanation, sort_order, points, required, graded)
  values (v_question, v_version, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'multiple_choice', '¿Cuál es el propósito principal del bloqueo y etiquetado?', 'El bloqueo y etiquetado evita el arranque inesperado o la liberación de energía almacenada mientras las personas dan servicio al equipo.', 0, 1, true, true);
  insert into public.strike_quiz_answers (question_id, tenant_id, library_scope, answer_text, is_correct, sort_order) values
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Evitar el arranque inesperado o la liberación de energía mientras se da servicio al equipo', true, 0),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Mantener la producción funcionando durante el mantenimiento', false, 1),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Registrar quién usó la máquina por última vez', false, 2),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Impedir que personas no autorizadas operen máquinas durante los descansos', false, 3);

