  insert into public.strike_quiz_questions
    (id, module_version_id, tenant_id, library_scope, question_type, prompt, explanation, sort_order, points, required, graded)
  values (v_question, v_version, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'multiple_choice', '¿Quién puede colocar un dispositivo de bloqueo?', 'Solo los empleados autorizados y capacitados colocan candados. Los empleados afectados reconocen los bloqueos, pero no los colocan.', 1, 1, true, true);
  insert into public.strike_quiz_answers (question_id, tenant_id, library_scope, answer_text, is_correct, sort_order) values
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Un empleado autorizado y capacitado', true, 0),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Cualquier empleado afectado que opere la máquina', false, 1),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Quien esté más cerca del desconector', false, 2),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Solo el gerente de la planta', false, 3);

  v_question := gen_random_uuid();
  insert into public.strike_quiz_questions
    (id, module_version_id, tenant_id, library_scope, question_type, prompt, explanation, sort_order, points, required, graded)
  values (v_question, v_version, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'true_false', 'Presionar el botón de paro de emergencia de la máquina es suficiente para aislar su energía.', 'Los botones de paro y los circuitos de control no son dispositivos de aislamiento de energía. Aísle en el desconector, la válvula o el bloque.', 2, 1, true, true);
  insert into public.strike_quiz_answers (question_id, tenant_id, library_scope, answer_text, is_correct, sort_order) values
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Verdadero', false, 0),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Falso', true, 1);

  v_question := gen_random_uuid();
  insert into public.strike_quiz_questions
    (id, module_version_id, tenant_id, library_scope, question_type, prompt, explanation, sort_order, points, required, graded)
  values (v_question, v_version, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'select_all', 'Seleccione cada fuente de energía que debe controlar en una máquina que tiene un motor, un cilindro de aire y una platina levantada.', 'El motor es eléctrico, el cilindro de aire es neumático y una platina levantada almacena energía por gravedad.', 3, 1, true, true);
  insert into public.strike_quiz_answers (question_id, tenant_id, library_scope, answer_text, is_correct, sort_order) values
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Eléctrica', true, 0),
