  v_question := gen_random_uuid();
  insert into public.strike_quiz_questions
    (id, module_version_id, tenant_id, library_scope, question_type, prompt, explanation, sort_order, points, required, graded)
  values (v_question, v_version, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'multiple_choice', '¿Qué sigue inmediatamente después de poner su candado y su etiqueta?', 'Después de bloquear y etiquetar, libere o contenga la energía almacenada y luego verifique.', 4, 1, true, true);
  insert into public.strike_quiz_answers (question_id, tenant_id, library_scope, answer_text, is_correct, sort_order) values
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Liberar o bloquear la energía almacenada', true, 0),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Empezar la reparación', false, 1),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Avisar a los empleados afectados', false, 2),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Quitar la guarda', false, 3);

