  insert into public.strike_quiz_questions
    (id, module_version_id, tenant_id, library_scope, question_type, prompt, explanation, sort_order, points, required, graded)
  values (v_question, v_version, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'multiple_choice', '¿Cómo verifica que una máquina está en energía cero?', 'Con todos alejados, intente arrancarla (una persona calificada hace cualquier prueba de voltaje que pida el procedimiento) y luego regrese los controles a apagado.', 5, 1, true, true);
  insert into public.strike_quiz_answers (question_id, tenant_id, library_scope, answer_text, is_correct, sort_order) values
