    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Mirar el candado para confirmar que está cerrado', false, 1),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Preguntarle al operador si está apagada', false, 2),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Esperar cinco minutos', false, 3);

  v_question := gen_random_uuid();
  insert into public.strike_quiz_questions
